const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const env = typeof $env === 'object' && $env ? $env : {};
const sourcePayload = $json.source_payload_json ?? {};
const contentId = String($json.content_id ?? '').trim();
const title = String($json.title ?? '').trim();
const narrationScript = String($json.narration_script ?? '').trim();
const isV2StoryPackage = String($json.is_v2_story_package ?? '').trim().toLowerCase() === 'true';
const sceneAssetCount = Number($json.scene_asset_count ?? 0);
const storyboardJson = Array.isArray($json.storyboard_json) ? $json.storyboard_json : [];
const creativeDefaults = sourcePayload.creative_defaults && typeof sourcePayload.creative_defaults === 'object' ? sourcePayload.creative_defaults : {};
const directorJson = $json.director_json && typeof $json.director_json === 'object' ? $json.director_json : {};
const normalizedDirectorVoiceRole = String(directorJson.voice_role ?? '').trim().toLowerCase();
const directorScenes = Array.isArray(directorJson.scenes) ? directorJson.scenes : [];
const directorTtsDelivery = String(directorJson.tts_delivery ?? '').trim();
const kidVoiceHintText = [
  creativeDefaults.voice_role_hint,
  creativeDefaults.narrator_style,
  sourcePayload.abstract_idea,
  title,
].map((value) => String(value || '').trim().toLowerCase()).filter(Boolean).join(' | ');
const kidVoiceHintPattern = / (kid|kids|child|children|school[- ]age|youngster|youthful|boy narrator|girl narrator|robot kid|kid robot) /;
const shouldPreferKidVoice = kidVoiceHintPattern.test(kidVoiceHintText);
const genericDirectorRoles = new Set(['', 'primary_male', 'documentary_narrator']);
const directorVoiceRole = shouldPreferKidVoice && genericDirectorRoles.has(normalizedDirectorVoiceRole)
  ? 'kid'
  : normalizedDirectorVoiceRole;
const VOICE_ROLE_ENV_MAP = {
  primary_male: ['FISH_AUDIO_VOICE_PRIMARY_MALE', 'FISH_AUDIO_REFERENCE_ID', 'FISH_AUDIO_VOICE_ID'],
  investigative_male: ['FISH_AUDIO_VOICE_INVESTIGATIVE_MALE', 'FISH_AUDIO_REFERENCE_ID', 'FISH_AUDIO_VOICE_ID'],
  urgent_male: ['FISH_AUDIO_VOICE_URGENT_MALE', 'FISH_AUDIO_REFERENCE_ID', 'FISH_AUDIO_VOICE_ID'],
  documentary_narrator: ['FISH_AUDIO_VOICE_DOCUMENTARY_NARRATOR', 'FISH_AUDIO_REFERENCE_ID', 'FISH_AUDIO_VOICE_ID'],
  kid: ['FISH_AUDIO_VOICE_KID', 'FISH_AUDIO_REFERENCE_ID', 'FISH_AUDIO_VOICE_ID'],
  primary_female: ['FISH_AUDIO_VOICE_PRIMARY_FEMALE', 'FISH_AUDIO_REFERENCE_ID_FEMALE'],
  calm_female: ['FISH_AUDIO_VOICE_CALM_FEMALE', 'FISH_AUDIO_REFERENCE_ID_FEMALE'],
};
const femaleRoles = new Set(['primary_female', 'calm_female']);
const defaultEnvKeys = femaleRoles.has(directorVoiceRole)
  ? ['FISH_AUDIO_REFERENCE_ID_FEMALE']
  : ['FISH_AUDIO_REFERENCE_ID', 'FISH_AUDIO_VOICE_ID'];
const voiceEnvKeys = VOICE_ROLE_ENV_MAP[directorVoiceRole] || defaultEnvKeys;
const directorVoiceReferenceId = voiceEnvKeys.reduce(
  (found, key) => found || String(env[key] || '').trim(),
  '',
);
const queueQueryReturnedNoCandidate = String($json.success ?? '').trim().toLowerCase() === 'true'
  && !contentId
  && !title
  && !narrationScript;
if (queueQueryReturnedNoCandidate) {
  throw new Error('No assets_ready content item with narration prerequisites is currently available for wf_narration_generation.');
}
if (!uuidPattern.test(contentId)) {
  throw new Error('Fetch Next Assets Ready Item returned an invalid content_id: ' + (contentId || '<empty>') + '.');
}
if (!title) {
  throw new Error('Fetch Next Assets Ready Item did not return title.');
}
if (!narrationScript) {
  throw new Error('Fetch Next Assets Ready Item did not return narration_script.');
}
if (sceneAssetCount < storyboardJson.length || sceneAssetCount < 4) {
  throw new Error('Fetch Next Assets Ready Item requires one ready visual asset per storyboard scene before narration generation.');
}
if (storyboardJson.length < 4) {
  throw new Error('Fetch Next Assets Ready Item requires storyboard_json before narration generation.');
}
const targetDurationSeconds = Number($json.target_duration_seconds ?? 45);
if (!Number.isFinite(targetDurationSeconds) || targetDurationSeconds <= 0) {
  throw new Error('target_duration_seconds must be a positive number.');
}
const defaultProvider = String(env.V2_NARRATION_PROVIDER || env.NARRATION_PROVIDER || env.TTS_PROVIDER || 'fish_audio').trim().toLowerCase() || 'fish_audio';
const defaultModel = String(env.V2_NARRATION_MODEL || env.NARRATION_MODEL || env.TTS_MODEL || env.FISH_AUDIO_TTS_MODEL || 's2-pro').trim() || 's2-pro';
const defaultVoice = String(directorVoiceReferenceId || env.V2_NARRATION_VOICE || env.NARRATION_VOICE || env.TTS_VOICE || env.FISH_AUDIO_REFERENCE_ID || env.FISH_AUDIO_VOICE_ID || '').trim();
const parsedSpeed = Number.parseFloat(String(isV2StoryPackage ? (env.V2_NARRATION_SPEED || env.NARRATION_SPEED || env.TTS_SPEED || '1') : (env.NARRATION_SPEED || env.TTS_SPEED || env.OPENAI_TTS_SPEED || '1')).trim());
const ttsSpeed = Number.isFinite(parsedSpeed)
  ? Math.min(4, Math.max(0.25, Number(parsedSpeed.toFixed(2))))
  : 1;
const responseFormat = String(env.V2_NARRATION_OUTPUT_FORMAT || env.NARRATION_OUTPUT_FORMAT || env.FISH_AUDIO_FORMAT || 'mp3').trim().toLowerCase() || 'mp3';
const sampleRateRaw = Number.parseInt(String(env.V2_NARRATION_SAMPLE_RATE || env.NARRATION_SAMPLE_RATE || env.FISH_AUDIO_SAMPLE_RATE || '24000').trim(), 10);
const sampleRate = Number.isFinite(sampleRateRaw) ? Math.min(44100, Math.max(8000, sampleRateRaw)) : 24000;
const ttsRequest = {
  provider: defaultProvider,
  model: defaultModel,
  voice: defaultVoice,
  speed: ttsSpeed,
  response_format: responseFormat,
  ...(isV2StoryPackage ? { output_format: responseFormat, sample_rate: sampleRate } : {}),
  ...(directorVoiceReferenceId ? { voice_reference_id: directorVoiceReferenceId } : {})
};
const payload = {
  content_id: contentId,
  title,
  narration_script: narrationScript,
  target_duration_seconds: targetDurationSeconds,
  storyboard_json: storyboardJson,
  workflow_name: 'wf_narration_generation',
  run_started_at: new Date().toISOString(),
  narration_provider: defaultProvider,
  is_v2_story_package: isV2StoryPackage,
  tts_request: ttsRequest,
  openai_tts_request: ttsRequest,
  prompt_profile: sourcePayload.prompt_profile ?? {},
  narration_style: String(creativeDefaults.narrator_style || creativeDefaults.voice_role_hint || '').trim(),
  director_voice_role: directorVoiceRole,
  director_tts_delivery: directorTtsDelivery,
  director_scenes: directorScenes,
  director_global_pacing: String(directorJson.global_pacing ?? '').trim(),
};
return [{
  json: {
    ...payload,
    rehost_payload_base64: Buffer.from(JSON.stringify(payload), 'utf8').toString('base64')
  }
}];

const stdout = String($json.stdout ?? '').trim();
if (!stdout) {
  throw new Error('Generate and Rehost Narration Audio produced no stdout.');
}
let parsed;
try {
  parsed = JSON.parse(stdout);
} catch (error) {
  throw new Error('Generate and Rehost Narration Audio returned invalid JSON: ' + error.message + '. Raw stdout: ' + stdout.slice(0, 500));
}
const scenes = Array.isArray(parsed.scenes) ? parsed.scenes : [];
if (scenes.length === 0) {
  throw new Error('The narration helper did not return a scenes array.');
}
for (const scene of scenes) {
  if (!String(scene.storage_url ?? '').trim()) {
    throw new Error('Scene ' + scene.scene_number + ' narration is missing storage_url.');
  }
  if (!String(scene.provider ?? '').trim()) {
    throw new Error('Scene ' + scene.scene_number + ' narration is missing provider.');
  }
}
return [{ json: parsed }];

const _cost = $json.cost ?? {};
const cost_json_sql = JSON.stringify(_cost).replaceAll("'", "''");
const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const contentId = String($json.content_id ?? '').trim();
if (!uuidPattern.test(contentId)) {
  throw new Error('Prepare Narration SQL Values received an invalid content_id: ' + (contentId || '<empty>') + '.');
}
const startedAt = new Date(String($json.run_started_at ?? new Date().toISOString()));
const durationMs = Math.max(0, Date.now() - startedAt.getTime());
const scenes = Array.isArray($json.scenes) ? $json.scenes : [];
const firstScene = scenes[0] ?? {};
const firstMeta = firstScene.metadata_json ?? {};
return [{
  json: {
    ...$json,
    content_id_sql: contentId,
    scenes_json_sql: JSON.stringify(scenes).replaceAll("'", "''"),
    workflow_name_sql: String($json.workflow_name ?? 'wf_narration_generation').replaceAll("'", "''"),
    generation_model_sql: String(firstMeta.generation_model ?? '').replaceAll("'", "''"),
    voice_sql: String(firstMeta.voice ?? '').replaceAll("'", "''"),
    scene_count_sql: scenes.length,
    total_duration_seconds_sql: Number.isFinite(Number($json.total_duration_seconds)) ? Number($json.total_duration_seconds) : 0,
    duration_ms_sql: Number.isFinite(durationMs) ? durationMs : 0,
    cost_json_sql
  }
}];
